  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeLangDropdown(); });
  document.addEventListener('click', (e) => {
    const dd = document.getElementById('lang-dropdown');
    if (dd && !dd.contains(e.target)) document.getElementById('lang-dropdown-menu').classList.add('hidden');
  });

  function switchTheme(theme) {
    localStorage.setItem('dhardi-theme', theme);
    document.documentElement.setAttribute('data-theme', theme);
    document.querySelectorAll('#theme-dark-btn, #theme-light-btn').forEach(btn => {
      const btnTheme = btn.id.replace('theme-', '').replace('-btn', '');
      if (btnTheme === theme) {
        btn.style.background = 'var(--bg-secondary)';
        btn.style.color = 'var(--text-primary)';
      } else {
        btn.style.background = 'transparent';
        btn.style.color = 'var(--text-muted)';
      }
    });
  }

  function openCVModal() {
    const lang = localStorage.getItem('dhardi-lang') || 'es';
    const t = i18n[lang];
    document.getElementById('modal-title').textContent = t.modal.cvTitle;
    document.getElementById('modal-image').innerHTML = `<div style="width:100%;padding:4rem 0;text-align:center;background:linear-gradient(135deg, var(--bg-card), var(--modal-bg));border-radius:0.75rem;color:var(--text-subtle);font-size:0.875rem;">📄 ${t.modal.cvPlaceholder}</div>`;
    document.getElementById('modal-description').textContent = t.modal.cvDesc;
    document.getElementById('modal-footer').innerHTML = `<a href="/cv.pdf" target="_blank" class="px-5 py-2 bg-[#e94560] text-white text-sm font-semibold rounded-lg hover:bg-[#d91a3a] transition-all">${t.modal.downloadCv}</a>`;
    document.getElementById('modal').classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    document.getElementById('modal').classList.remove('active');
    document.body.style.overflow = '';
  }

  function closeCertModal() {
    document.getElementById('cert-overlay').classList.remove('active');
    document.body.style.overflow = '';
  }
  function openCertModal() {
    document.getElementById('cert-overlay').classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeModal(); closeCertModal(); } });

  function toggleMobileNav() {
    document.getElementById('mobile-nav-menu').classList.toggle('open');
    document.getElementById('mobile-nav-backdrop').classList.toggle('open');
    document.getElementById('mobile-nav-toggle').classList.toggle('open');
  }
  function closeMobileNav() {
    document.getElementById('mobile-nav-menu').classList.remove('open');
    document.getElementById('mobile-nav-backdrop').classList.remove('open');
    document.getElementById('mobile-nav-toggle').classList.remove('open');
  }
  document.addEventListener('scroll', closeMobileNav, { passive: true });
  window.addEventListener('resize', () => { if (window.innerWidth >= 768) closeMobileNav(); });

  // ===== Slideshow =====
  const slides = document.querySelectorAll('.bg-slide');
  const totalSlides = slides.length;
  let current = 0;
  let interval;

  function getVibeLabels() {
    const lang = localStorage.getItem('dhardi-lang') || 'es';
    const t = i18n[lang];
    return t.vibe || ['Matterhorn · Switzerland ❄️', 'Punta Cana · Dominican Republic ☀️', 'Swiss Alps ⛰️', 'Pico Duarte · Jarabacoa 🏔️', 'Zürich · Switzerland 🏙️', 'Tropical Sunset · Caribbean 🌅', 'Swiss Alps Village 🏡', 'Dominican Republic Coast 🌊'];
  }

  const vibeEl = document.getElementById('vibe-label');
  const vibeIcon = document.getElementById('vibe-icon');
  const vibeCounter = document.getElementById('vibe-counter');
  const overlay = document.getElementById('hero-overlay');

  function goToSlide(index) {
    slides[current].classList.remove('active', 'kenburns');
    current = (index + totalSlides) % totalSlides;
    slides[current].classList.add('active', 'kenburns');
    updateVibe();
  }

  function nextSlide() { goToSlide(current + 1); }
  function prevSlide() { goToSlide(current - 1); }

  function updateVibe() {
    vibeCounter.textContent = `${current + 1}/${totalSlides}`;
    const isSwiss = current === 0 || current === 2 || current === 4 || current === 6;
    vibeIcon.textContent = isSwiss ? '❄️' : '☀️';
    vibeEl.textContent = getVibeLabels()[current];
    overlay.style.background = isSwiss
      ? 'linear-gradient(135deg, rgba(5,5,30,0.88) 0%, rgba(5,5,20,0.8) 50%, rgba(15,10,25,0.85) 100%)'
      : 'linear-gradient(135deg, rgba(30,10,5,0.85) 0%, rgba(5,5,5,0.8) 50%, rgba(25,15,5,0.85) 100%)';
  }

  function startSlideshow() { clearInterval(interval); interval = setInterval(nextSlide, 6000); }
  function stopSlideshow() { clearInterval(interval); }

  slides[0].classList.add('active', 'kenburns');
  startSlideshow();

  document.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') { stopSlideshow(); prevSlide(); startSlideshow(); }
    if (e.key === 'ArrowRight') { stopSlideshow(); nextSlide(); startSlideshow(); }
  });

  // Drag
  let isDragging = false;
  let dragStartX = 0;
  const bgSlideshow = document.getElementById('bg-slideshow');
  bgSlideshow.addEventListener('mousedown', e => { isDragging = true; dragStartX = e.screenX; bgSlideshow.style.cursor = 'grabbing'; });
  document.addEventListener('mousemove', e => {
    if (!isDragging) return;
    const diff = dragStartX - e.screenX;
    if (Math.abs(diff) > 80) {
      stopSlideshow();
      if (diff > 0) nextSlide(); else prevSlide();
      startSlideshow();
      isDragging = false;
      bgSlideshow.style.cursor = 'grab';
    }
  });
  document.addEventListener('mouseup', () => { isDragging = false; bgSlideshow.style.cursor = 'grab'; });

  // Touch swipe
  const hero = document.getElementById('hero');
  let touchStartX = 0;
  hero.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; }, { passive: true });
  hero.addEventListener('touchend', e => {
    const diff = touchStartX - e.changedTouches[0].screenX;
    if (Math.abs(diff) > 50) {
      stopSlideshow();
      if (diff > 0) nextSlide(); else prevSlide();
      startSlideshow();
    }
  }, { passive: true });

  hero.addEventListener('mouseenter', stopSlideshow);
  hero.addEventListener('mouseleave', startSlideshow);

  // ===== Cert Spinner =====
  const certFrames = ['◴', '◷', '◶', '◵'];
  let certIdx = 0;
  setInterval(() => { const el = document.getElementById('cert-spinner'); if (el) el.textContent = certFrames[certIdx++ % certFrames.length]; }, 400);
  setInterval(() => {
    const el = document.getElementById('cert-bar');
    if (!el) return;
    const w = parseInt(el.style.width) || 42;
    el.style.width = Math.min(99, w + (Math.random() > 0.7 ? 1 : 0)) + '%';
  }, 3000);

  // ===== Scroll reveal =====
  const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => { if (entry.isIntersecting) entry.target.classList.add('visible'); });
  }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });
  document.querySelectorAll('.section-in').forEach(el => revealObserver.observe(el));

  // ===== Scroll spy =====
  const navLinks = document.querySelectorAll('nav a[href^="#"]');
  const spySections = document.querySelectorAll('section[id]');
  const spyObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const id = entry.target.id;
        navLinks.forEach(link => {
          link.classList.remove('text-primary');
          link.classList.add('text-muted');
          if (link.getAttribute('href') === '#' + id) {
            link.classList.remove('text-muted');
            link.classList.add('text-primary');
          }
        });
      }
    });
  }, { threshold: 0.3, rootMargin: '0px 0px -100px 0px' });
  spySections.forEach(s => spyObserver.observe(s));

  // ===== Tech Stack interaction =====
  const techPopup = document.getElementById('tech-popup');
  const techDesc = document.getElementById('tech-desc');

  document.querySelectorAll('#tech-grid > div').forEach(el => {
    const label = el.querySelector('span:last-child')?.textContent.trim();
    el.addEventListener('click', () => {
      const lang = localStorage.getItem('dhardi-lang') || 'es';
      const techInfo = i18n[lang].tech || {};
      if (!techInfo[label]) return;
      techDesc.textContent = `${label} — ${techInfo[label]}`;
      techPopup.innerHTML = `<span class="tp-label">${label}</span> — ${techInfo[label]}`;
      const rect = el.getBoundingClientRect();
      const pw = techPopup.offsetWidth || 280;
      const ph = techPopup.offsetHeight || 80;
      let left = rect.left + rect.width / 2 - pw / 2;
      left = Math.max(16, Math.min(left, window.innerWidth - pw - 16));
      techPopup.style.left = left + 'px';
      if (rect.bottom + ph + 8 > window.innerHeight) {
        techPopup.style.top = Math.max(8, rect.top - ph - 8) + 'px';
      } else {
        techPopup.style.top = rect.bottom + 8 + 'px';
      }
      techPopup.classList.add('show');
      clearTimeout(techPopup._hide);
      techPopup._hide = setTimeout(() => techPopup.classList.remove('show'), 2500);
    });
  });

  // ===== Header scroll =====
  const header = document.getElementById('header');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 100) header.classList.add('inMoved'); else header.classList.remove('inMoved');
  }, { passive: true });

  // ===== Initialize =====
  (function init() {
    const savedLang = localStorage.getItem('dhardi-lang') || 'es';
    const savedTheme = localStorage.getItem('dhardi-theme') || 'dark';
    switchLanguage(savedLang);
    switchTheme(savedTheme);
  })();
</script>

