    <Skill icon="React" />
    <Skill icon="Node" />
    <Skill icon="Express" />
    <!-- 8 more skills -->
  </div>
</section>

<script>
  const TOTAL_COLS = 6;
  const grid = document.querySelector(".skills-grid")!;
  const cards = grid.querySelectorAll<HTMLElement>("[data-skill]");

  function activate(card: HTMLElement) {
    const colStart = getColStart(card);

    if (colStart + 1 > TOTAL_COLS) {
      card.style.gridColumnStart = String(TOTAL_COLS - 1);
    }

    grid.classList.remove("grid-flow-dense");  // Freeze grid layout

    cards.forEach((c) => {
      if (c !== card) {
        c.classList.add("opacity-20", "scale-95");
      }
    });

    card.classList.add("!col-span-2", "!row-span-2", "is-active");
  }

  function deactivate() {
    cards.forEach((c) => {
      c.style.gridColumnStart = "";
      c.classList.remove("opacity-20", "scale-95", "!col-span-2", "!row-span-2", "is-active");
    });
    grid.classList.add("grid-flow-dense");  // Restore dense packing
  }

  grid.addEventListener("mouseover", (e) => {
    const card = (e.target as HTMLElement).closest<HTMLElement>("[data-skill]");
    if (!card || grid.querySelector(".is-active") === card) return;
    deactivate();
    activate(card);
  });

  grid.addEventListener("mouseleave", () => {
    deactivate();
  });
</script>
```

**Skill Card Component:** `/tmp/repo/src/components/Skill.astro`

```astro
<article
  data-skill
  class={`skill-card group relative overflow-hidden rounded-2xl p-4 md:p-10
          transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)] cursor-pointer ${className}`}
>
  <!-- Icon view (default) -->
  <div class="skill-icon transition-all duration-400 ease-in-out w-full h-full flex flex-col gap-6 items-center justify-center">
    <Icon class="w-full h-full" />
    <p class="text-carbon/90 dark:text-yellow-50 font-stretch-ultra-condensed">
      {found?.name ?? nameIcon}
    </p>
  </div>

  <!-- Info view (expanded) -->
  <div class="skill-info absolute inset-0 flex flex-col justify-center items-center gap-3 opacity-0 pointer-events-none transition-all duration-300">
    <Icon class="w-12 h-12 size-full shrink-0" />
    <div class="flex flex-col items-center gap-2">
      <span class="text-red-200 font-bold text-lg tracking-wide">
        {found?.name ?? nameIcon}
      </span>
      <span class="bg-yellow-200 text-red-950 font-semibold text-xs tracking-wide px-2 py-1 rounded-sm">
        {found.categorie}
      </span>
    </div>
    {found?.description && (
      <p class="text-blue-50/90 text-sm text-center leading-relaxed text-pretty">
        {found.description}
      </p>
    )}
    {found?.tags && (
      <div class="flex flex-wrap gap-2 justify-center">
        {found.tags.map((tag: string) => (
          <span class="text-xs px-2 py-1 rounded-full border-2 bg-slate-50 border-gray-700/20 text-blue-950">
            {tag}
          </span>
        ))}
      </div>
    )}
  </div>
</article>

<style>
  @media screen and (min-width: 768px) {
    .is-active .skill-info {
      opacity: 1;
      pointer-events: auto;
    }

    .is-active .skill-icon {
      opacity: 0;
    }
  }
</style>
```

**Key Features:**
- 6-column masonry layout with `grid-flow-dense`
- On hover: card expands to 2x2 grid cells with smooth transition
- Other cards fade to 20% opacity and scale to 95%
- Grid layout freezes during expansion to prevent reflow
- Shows skill description, category tag, and relevant tags

---

### **5. NO DEDICATED SERVICES SECTION**

This portfolio does **not** have a separate services section. Instead, it showcases:
- **Hero section** with intro
- **About section** 
- **Projects section** (with 3 detailed full-stack projects)
- **Skills section** (14 technologies)
- **Certifications section**
- **Contact section**

---

### **6. OVERALL CSS/JS PATTERNS & ANIMATIONS**

**Animation Library Usage:** The portfolio uses **Tailwind Animations** + **Motion (Framer Motion for React)**

**Available Animations (from config):**
```
- animate-aurora (8s rotating gradient)
- animate-blink (range-based scroll animation)
- animate-blurred-fade-in
- animate-slide-in-top/left/right
- animate-rotational-wave
- animate-pulse
- animate-range-[entry_X%_cover_Y%] (scroll-triggered)
```

**Example Animation Usage:**

```astro
<!-- Hero section with staggered blur fade animations -->
<BlurFadeTW delay={0.25} client:load>
  <h3 class="text-2xl md:text-3xl font-medium">
    Hola! Mi Nombre es
  </h3>
</BlurFadeTW>

<BlurFadeTW delay={0.5} client:load>
  <AuroraWrapper client:load> Sergio Hernández </AuroraWrapper>
</BlurFadeTW>

<BlurFadeTW delay={0.75} client:load>
  <BadgeAvaible client:load>
    Disponible para nuevas oportunidades
  </BadgeAvaible>
</BlurFadeTW>
```

**BlurFade Component:** `/tmp/repo/src/components/ui/blur-fade.tsx`
Uses Motion library with:
- Initial blur filter on entrance
- Smooth fade-in with optional directional offset
- Configurable delay and duration
- InView detection for scroll-based triggering

```typescript
export function BlurFade({
  children,
  duration = 0.4,
  delay = 0,
  offset = 6,
  direction = "down",
  inView = false,
  blur = "6px",
}: BlurFadeProps) {
  const defaultVariants: Variants = {
    hidden: {
      [direction === "left" || direction === "right" ? "x" : "y"]:
        direction === "right" || direction === "down" ? -offset : offset,
      opacity: 0,
      filter: `blur(${blur})`,
    },
    visible: {
      [direction === "left" || direction === "right" ? "x" : "y"]: 0,
      opacity: 1,
      filter: `blur(0px)`,
    },
  }
  // ... motion.div with these variants
}
```

**Aurora Text Effect:** Special animated gradient text on hero name
**Typing Animation:** "Software Developer" text types out on load

**Color System:** 
- Primary: `#d90429` (red)
- Secondary: `#f5bb00` (gold/yellow)
- Multiple variants for each (500, 600, 700, 800 shades)
- All using OKLCH color space for better perceptual uniformity

**Layout Patterns:**
- Sticky navbar with scroll detection
- Fixed right-side dot navigation with IntersectionObserver
- Mobile menu with transform animations
- Glass-morphism effects (backdrop-filter: blur)
- Responsive grid layouts

**Transition Timing:**
- Most UI transitions: 300ms ease-out
- Navbar: 300ms ease
- Grid expansions: 500ms cubic-bezier(0.4, 0, 0.2, 1)
- Skill info: 300-400ms

---

## Key Technical Stack

- **Framework:** Astro 6.0 with View Transitions (no SPA refresh)
- **Styling:** Tailwind CSS 4.2 + custom theme variables
- **Animations:** 
  - Tailwind-animations for CSS keyframes
  - Motion/Framer Motion for React components
  - tw-animate-css for additional effects
- **Interactivity:** Vanilla JavaScript + React for interactive components
- **Icons:** lucide-react (embedded as Astro components)
- **Color Management:** Custom utility functions converting hex to RGBA
- **State:** React hooks for theme toggle, no global state manager needed
- **Deployment:** Vercel adapter configured

This is a **highly polished, animation-heavy portfolio** that prioritizes visual excellence and smooth user experience without traditional page navigations.

