.btn-detail {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 0.5rem 1rem; font-size: 0.8rem; font-weight: 600;
  background: #e94560; color: #fff; border-radius: 0.5rem;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none; position: relative; overflow: hidden;
}
.btn-detail::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,0.15), transparent);
  opacity: 0; transition: opacity 0.3s ease;
}
.btn-detail:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(233, 69, 96, 0.45);
}
.btn-detail:hover::before { opacity: 1; }
.btn-detail:hover .btn-detail-arrow { transform: translateX(3px); }
.btn-detail:active { transform: translateY(0) scale(0.97); }
.btn-detail-arrow { transition: transform 0.25s ease; }

